'use client';

import { useQuery } from '@tanstack/react-query';

import { QueryKeys } from '@/constants/query-keys';
import { getSmartBlockHistoricalSuggestions } from '@/services/smartBlock';

export function useSmartBlockHistoricalSuggestionsQuery(
    smartBlockId: number | string | null | undefined,
) {
    return useQuery({
        queryKey: [QueryKeys.smartBlock.historicalSuggestions, smartBlockId],
        queryFn: () => getSmartBlockHistoricalSuggestions(smartBlockId),
        enabled: !!smartBlockId,
    });
}

