1	import { formatCurrency } from '@/functions/formaters/formatCurrency';
2	import numberFormat from '@/functions/formaters/numberFormat';
3	import { getSliderThumbOffsetStyle } from '@/functions/slider/getSliderThumbOffsetStyle';
