'use client';

import { SemSmartblockAlert } from '@/components/CRM/Broker/SemSmartblockAlert';
import { SemSmartblockSliderFrost } from '@/components/CRM/Broker/SemSmartblockSliderFrost';
import { ErrorMessageBox } from '@/components/ErrorMessage/ErrorMessageBox';
import { ValueCardsAndSliderSkeleton } from '@/components/Skeletons/Broker/ValueCardsAndSliderSkeleton';
import { LockedSectionTooltip } from '@/components/Tooltips/LockedSectionTooltip';
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from '@/components/ui/tooltip';
import AnimatedNumber from '@/components/ui/AnimatedNumber';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { defaultProfilePicture } from '@/constants/profile_default';
import { QueryKeys } from '@/constants/query-keys';
import { statusPropostaBloqueantesDeLiquidacao } from '@/constants/status';
import { PERCENTAGE_FACTOR, SLIDER_STEP } from '@/components/Sliders/constants';
import {
    getBackendErrorAnalyticsProps,
    getUserFacingApiMessage,
} from '@/functions/analytics/axiosErrorProps';
import { debounce } from '@/functions/debounce';
import { formatCurrency } from '@/functions/formaters/formatCurrency';
import numberFormat from '@/functions/formaters/numberFormat';
import { sendToastMessage } from '@/functions/messages/toastMessage';
import { getSliderThumbOffsetStyle } from '@/functions/slider/getSliderThumbOffsetStyle';
import { hasCreditorAcceptRecorded } from '@/functions/oficios/broker-oficio-details-actions';
import { useIsLocalhost } from '@/lib/runtime/is-localhost';
import { isProposalSemSmartblock } from '@/functions/propostas/is-proposal-sem-smartblock';
import { resolvePropostaSliderPricingInput } from '@/functions/repactuacao/resolve-proposta-slider-pricing';
import { useExtratoDataQueryOptions } from '@/hooks/queries/extrato';
import { useSmartBlockHistoricalSuggestionsQuery } from '@/hooks/queries/smart-block-historical-suggestions';
import { getSmartBlockById } from '@/services/smart-blocks';
import { resolveBrokerPricingEngine } from '@/functions/finance/comissao-broker';
import { cn } from '@/lib/utils';
import { declineCurrentProposal, saveProposalAndComission } from '@/services/BrokerServices';
import { useBrokerStore } from '@/store/useBroker';
import { useUserInfoStore } from '@/store/userInfo';
import { DetailedOficioProps } from '@/types/oficio';
import queryClient from '@/utils/queryClient';
import { useMutation, useQuery } from '@tanstack/react-query';
import { ArrowLeft, ArrowRight, Pencil, Save, X, Landmark, HandCoins, PiggyBank, Star } from 'lucide-react';
import posthog from 'posthog-js';
import { parseAsString, useQueryState } from 'nuqs';
import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import dynamic from 'next/dynamic';
import {
    BROKER_ACCEPT_ACCENT_TEXT_CLASS,
    BROKER_ACCEPT_BUTTON_CLASS,
    BROKER_ACCEPT_SLIDER_FOCUS_CLASS,
    BROKER_ACCEPT_SURFACE_CLASS,
    BROKER_BRAND_ACCENT_TEXT_CLASS,
    BROKER_BRAND_BUTTON_CLASS,
    BROKER_BRAND_SLIDER_FOCUS_CLASS,
    resolveBrokerPricingAccent,
} from '../_constants/pricing-accents';
import { DesfazerAceitePropostaModal } from './DesfazerAceitePropostaModal';
import { EarnOutBlock } from './EarnOutBlock';
import { fetchLatestPropostaDigitalDocumentOrNull } from '@/services/proposta-digital';
import { useDriverTour } from '@/components/ui/driver-tour';
import {
    animateCursorToGerarProposta,
    animateCursorToRegua,
    killCursorGuide,
    BROKER_PRICING_TOUR_IDS,
    createBrokerPricingTourConfig,
    launchBrokerProposalWizardTour,
    markMovedRegua,
    parsePropostaDigitalQuery,
    PROPOSTA_DIGITAL_QUERY,
    PROPOSTA_DIGITAL_QUERY_KEY,
    registerBrokerPricingTourOnCompleted,
} from '@/app/crm/broker/_components/activation';
import {
    formatProposalId,
    type BrandKit,
    type ProposalGeneratorProposal,
    type ProposalWizardMode,
} from './ProposalWizard';
import { isPropostaDigitalSentLike } from './ProposalWizard/utils/hasSentDigitalProposal';

const ProposalWizardDialog = dynamic(
    () => import('./ProposalWizard').then((mod) => ({ default: mod.ProposalWizardDialog })),
    { ssr: false },
);
import {
    compareDigitalOfferToCurrent,
    parseOfferAmount,
} from './ProposalWizard/utils/compareDigitalOffer';
import { GlarePrimaryButton } from './ProposalWizard/atoms';

type ValueCardTone = 'brand' | 'amber' | 'success';

const VALUE_CARD_SHELL: Record<
    ValueCardTone,
    { card: string; icon: string; value: string; iconWrap: string }
> = {
    brand: {
        card: 'border-[color-mix(in_srgb,#1c64f2_22%,var(--bento-card-border))] bg-[color-mix(in_srgb,#1c64f2_5%,var(--bento-card))]',
        iconWrap:
            'border-[color-mix(in_srgb,#1c64f2_28%,var(--bento-card-border))] bg-[color-mix(in_srgb,#1c64f2_10%,var(--bento-shell))] text-[#1c64f2]',
        icon: 'text-[#1c64f2]',
        value: 'text-[#1c64f2] dark:text-blue-300',
    },
    amber: {
        card: 'border-[color-mix(in_srgb,#f59e0b_24%,var(--bento-card-border))] bg-[color-mix(in_srgb,#f59e0b_5%,var(--bento-card))]',
        iconWrap:
            'border-[color-mix(in_srgb,#f59e0b_28%,var(--bento-card-border))] bg-[color-mix(in_srgb,#f59e0b_10%,var(--bento-shell))] text-amber-700 dark:text-amber-300',
        icon: 'text-amber-700 dark:text-amber-300',
        value: 'text-amber-800 dark:text-amber-200',
    },
    success: {
        card: 'border-[color-mix(in_srgb,#10b981_24%,var(--bento-card-border))] bg-[color-mix(in_srgb,#10b981_5%,var(--bento-card))]',
        iconWrap:
            'border-[color-mix(in_srgb,#10b981_28%,var(--bento-card-border))] bg-[color-mix(in_srgb,#10b981_10%,var(--bento-shell))] text-emerald-700 dark:text-emerald-300',
        icon: 'text-emerald-700 dark:text-emerald-300',
        value: 'text-emerald-800 dark:text-emerald-200',
    },
};

const BENTO_SURFACE =
    'rounded-xl border border-(--bento-card-border) bg-[color-mix(in_srgb,var(--bento-card)_94%,transparent)]';
const BENTO_INSET =
    'rounded-lg border border-(--bento-card-border) bg-[color-mix(in_srgb,var(--bento-shell)_78%,transparent)]';

interface ValueMetricCardProps {
    tone: ValueCardTone;
    icon: typeof Landmark;
    label: string;
    className?: string;
    children: React.ReactNode;
}

function ValueMetricCard({ tone, icon: Icon, label, className, children }: ValueMetricCardProps) {
    const styles = VALUE_CARD_SHELL[tone];

    return (
        <div
            className={cn(
                'flex min-w-0 flex-col items-center justify-center rounded-xl border p-2.5 shadow-sm',
                'sm:p-3 2xl:p-3.5',
                styles.card,
                className,
            )}
        >
            <div className="mb-1.5 flex items-center gap-1.5 sm:mb-2 sm:gap-2">
                <div
                    className={cn(
                        'flex size-6 shrink-0 items-center justify-center rounded-lg border sm:size-7',
                        styles.iconWrap,
                    )}
                >
                    <Icon size={14} strokeWidth={2.25} aria-hidden />
                </div>
                <h3
                    className={cn(
                        'text-[10px] font-semibold leading-tight text-(--bento-text-muted) sm:text-[11px]',
                        styles.icon,
                    )}
                >
                    {label}
                </h3>
            </div>
            {children}
        </div>
    );
}

function ValueAmount({ tone, children, className }: { tone: ValueCardTone; children: React.ReactNode; className?: string }) {
    return (
        <p
            className={cn(
                'max-w-full whitespace-nowrap font-mono text-base font-bold tabular-nums tracking-tight',
                'sm:text-lg xl:text-xl 2xl:text-2xl',
                VALUE_CARD_SHELL[tone].value,
                className,
            )}
        >
            {children}
        </p>
    );
}

export function ValueCardsAndSlider() {
    // =================
    // # Store
    // =================
    const extratoId = useBrokerStore((store) => store.extratoId);
    const isLocalhost = useIsLocalhost();
    const {
        data: {
            first_name,
            last_name,
            phone,
            email,
            title,
            nome_fantasia,
            razao_social,
            cidade,
            estado,
            profile_picture,
        },
    } = useUserInfoStore();

    // =================
    // # Data Hooks
    // =================
    const {
        data: extratoData,
        isError: isErrorExtratoData,
        refetch: refetchExtratoData,
        isFetching: isFetchingExtratoData,
    } = useQuery(useExtratoDataQueryOptions(extratoId));
    const proposalData = extratoData?.propostas?.find((p) => p.vigente);
    const { data: smartBlock } = useQuery({
        queryKey: [QueryKeys.smartBlock.detail, proposalData?.smart_block],
        queryFn: () => getSmartBlockById(String(proposalData?.smart_block)),
        enabled: proposalData?.smart_block != null,
        refetchOnMount: 'always',
        staleTime: 0,
    });

    // =================
    // # States
    // =================
    const [proposalValue, setProposalValue] = useState<number>(0);
    const [isEditingProposal, setIsEditingProposal] = useState<boolean>(false);
    const [isSaving, setIsSaving] = useState<boolean>(false);
    const [inputError, setInputError] = useState<boolean>(false);
    const [inputValue, setInputValue] = useState<string>('');
    const [wizardOpen, setWizardOpen] = useState(false);
    const [wizardMode, setWizardMode] = useState<ProposalWizardMode>('edit');
    const [wizardInitialStep, setWizardInitialStep] = useState<number | undefined>(undefined);
    const [wizardTourPending, setWizardTourPending] = useState(false);
    const [hasSentDigital, setHasSentDigital] = useState(false);
    const [publishedDigitalOffer, setPublishedDigitalOffer] = useState<number | null>(null);
    const [undoAcceptModalOpen, setUndoAcceptModalOpen] = useState(false);
    const [propostaDigitalRaw, setPropostaDigitalQuery] = useQueryState(
        PROPOSTA_DIGITAL_QUERY_KEY,
        parseAsString,
    );
    const savesInFlightRef = useRef(0);
    const extratoIdForAnalyticsRef = useRef<string | null>(null);
    const proposalValueInputRef = useRef<HTMLInputElement>(null);
    const acceptedValueSnapshotRef = useRef<number>(0);
    /** Valor arrastado no slider enquanto o aceite ainda está registrado (null no caminho do lápis). */
    const pendingProposalValueRef = useRef<number | null>(null);

    extratoIdForAnalyticsRef.current = extratoId ?? null;

    const captureSliderChangeDebounced = useMemo(
        () =>
            debounce((numValue: number) => {
                const id = extratoIdForAnalyticsRef.current;
                if (!id) return;
                posthog.capture('crm_broker_details_proposal_slider_changed', {
                    extrato_id: id,
                    new_value: numValue,
                });
            }, 450),
        [],
    );

    // =================
    // # Constants
    // =================
    const minCommissionCoordinator = Number(proposalData?.comissao_minima_coordenador) || 0;
    const maxCommissionCoordinator = Number(proposalData?.comissao_maxima_coordenador) || 0;
    const valorLiquidoExtrato = Number(extratoData?.valor_liquido_disponivel) || 0;
    const isArchived = extratoData?.arquivado ?? false;
    const proposalStatus = proposalData?.status as string;
    const hasAcceptRecorded = hasCreditorAcceptRecorded(proposalStatus);
    const isLiquidated = statusPropostaBloqueantesDeLiquidacao.includes(proposalStatus);
    const isHardLocked = isArchived || (isLiquidated && !hasAcceptRecorded);
    const isLocked = isHardLocked;
    const isSemSmartblock = isProposalSemSmartblock(proposalData);
    const isPricingLocked = isLocked || isSemSmartblock;
    const pricingAccent = resolveBrokerPricingAccent(hasAcceptRecorded);
    const pricingAccentMuted = hasAcceptRecorded
        ? BROKER_ACCEPT_ACCENT_TEXT_CLASS
        : BROKER_BRAND_ACCENT_TEXT_CLASS;
    const pricingFocusRing = hasAcceptRecorded
        ? BROKER_ACCEPT_SLIDER_FOCUS_CLASS
        : BROKER_BRAND_SLIDER_FOCUS_CLASS;
    // Régua efetiva: com repactuação V2 aberta vale a proposta_nova — SmartBlock
    // rematchado pro VL novo + exceção do broker já resolvidos no backend — não
    // a faixa congelada da proposta vigente.
    const pricingInput = useMemo(
        () =>
            resolvePropostaSliderPricingInput({
                dueDiligence: extratoData?.due_diligence,
                proposalData,
                smartBlock,
                valorLiquidoExtrato,
            }),
        [extratoData?.due_diligence, proposalData, smartBlock, valorLiquidoExtrato],
    );
    const sliderBounds = pricingInput.bounds;
    const minProposal = sliderBounds.minProposal;
    const maxProposal = sliderBounds.maxProposal;
    const valorLiquido = pricingInput.valorLiquido;
    const pricingEngine = useMemo(
        () =>
            resolveBrokerPricingEngine({
                smartBlock: pricingInput.smartBlock,
                exceptionId: pricingInput.exceptionId,
                exceptionPricing: pricingInput.exceptionPricing,
                valorLiquido: pricingInput.valorLiquido,
                baseDesembolso: pricingInput.baseDesembolso,
                bounds: pricingInput.bounds,
                coordinatorBounds: { min: minCommissionCoordinator, max: maxCommissionCoordinator },
            }),
        [pricingInput, minCommissionCoordinator, maxCommissionCoordinator],
    );
    const { data: suggestions } = useSmartBlockHistoricalSuggestionsQuery(
        isLocalhost ? proposalData?.smart_block : null,
    );

    const suggestedProposal = useMemo(() => {
        const raw = suggestions?.suggested_proposal;
        if (raw == null || raw <= 0 || !proposalData) return 0;
        return Math.min(Math.max(raw, minProposal), maxProposal);
    }, [suggestions, proposalData, minProposal, maxProposal]);

    const suggestedProposalPct = useMemo(() => {
        if (maxProposal === minProposal || suggestedProposal === 0) return 0;
        return Math.max(
            0,
            Math.min(
                PERCENTAGE_FACTOR,
                ((suggestedProposal - minProposal) / (maxProposal - minProposal)) * PERCENTAGE_FACTOR,
            ),
        );
    }, [suggestedProposal, minProposal, maxProposal]);

    const displayedCommission = useMemo(() => {
        if (!proposalData) return 0;

        return pricingEngine.resolveCommissionForDisplay(
            pricingInput.propostaEscolhida,
            pricingInput.comissaoEscolhida,
            proposalValue,
        );
    }, [proposalValue, proposalData, pricingEngine, pricingInput]);

    const sliderPercentage = useMemo(() => {
        if (maxProposal === minProposal) return 0;
        return ((proposalValue - minProposal) / (maxProposal - minProposal)) * 100;
    }, [proposalValue, minProposal, maxProposal]);

    // =================
    // # Handlers
    // =================
    const saveProposalValues = useCallback(
        async (proposal: number, commission: number, commissionCoord: number) => {
            if (!proposalData) return;
            savesInFlightRef.current += 1;
            setIsSaving(true);
            try {
                posthog.capture('crm_broker_details_proposal_save_started', {
                    extrato_id: extratoId,
                    proposal_value: proposal,
                    commission_broker: commission,
                });
                await saveProposalAndComission(proposalData.uuid, {
                    proposal,
                    commissionBroker: commission,
                    commissionCoordinator: commissionCoord,
                });
                queryClient.setQueryData(
                    [QueryKeys.oficios.item, extratoId],
                    (old: DetailedOficioProps) => {
                        return {
                            ...old,
                            propostas: old.propostas.map((p) =>
                                p.uuid === proposalData.uuid
                                    ? {
                                          ...p,
                                          proposta_escolhida: proposal,
                                          comissao_escolhida: commission,
                                          comissao_escolhida_coordenador: commissionCoord,
                                      }
                                    : p,
                            ),
                        };
                    },
                );
                queryClient.invalidateQueries({
                    queryKey: [QueryKeys.broker.dashboardTable],
                    refetchType: 'all',
                });
                queryClient.invalidateQueries({
                    queryKey: [QueryKeys.broker.cardInfoValues],
                    refetchType: 'all',
                });
                queryClient.invalidateQueries({
                    queryKey: [QueryKeys.broker.dashboardCharts],
                    refetchType: 'all',
                });
                posthog.capture('crm_broker_details_proposal_save_success', {
                    extrato_id: extratoId,
                    proposal_value: proposal,
                });
                sendToastMessage({
                    title: 'Proposta e comissão atualizadas com sucesso!',
                    type: 'success',
                });
            } catch (error) {
                posthog.capture('crm_broker_details_proposal_save_failed', {
                    extrato_id: extratoId,
                    error: error instanceof Error ? error.message : 'Unknown error',
                    ...getBackendErrorAnalyticsProps(error),
                });
                sendToastMessage({
                    title: 'Erro ao salvar proposta',
                    description: getUserFacingApiMessage(
                        error,
                        'Não foi possível atualizar a proposta. Tente novamente.',
                    ),
                    type: 'error',
                });
                console.error('Erro ao salvar proposta:', error);
            } finally {
                savesInFlightRef.current = Math.max(0, savesInFlightRef.current - 1);
                if (savesInFlightRef.current === 0) setIsSaving(false);
            }
        },
        [proposalData, extratoId],
    );

    const debouncedSave = useMemo(() => debounce(saveProposalValues, 2000), [saveProposalValues]);

    /**
     * "Mudar e retirar": retira o aceite e, quando o broker arrastou o slider
     * antes de confirmar (`pendingProposalValueRef`), persiste o novo valor —
     * `reverter-proposta` primeiro (o backend não deixa editar uma proposta
     * ainda aceita), depois `editar-proposta`.
     */
    const changeAndRemoveAcceptMutation = useMutation({
        mutationFn: async () => {
            if (!proposalData?.uuid) {
                throw new Error('Proposta não encontrada para retirar o aceite.');
            }
            await declineCurrentProposal(proposalData.uuid);

            const target = pendingProposalValueRef.current;
            if (
                target != null &&
                Math.round(target) !== Math.round(acceptedValueSnapshotRef.current)
            ) {
                const commission = pricingEngine.calculateCommissionForProposal(target);
                const commissionCoord = pricingEngine.calculateCoordinatorCommission(commission);
                await saveProposalAndComission(proposalData.uuid, {
                    proposal: target,
                    commissionBroker: commission,
                    commissionCoordinator: commissionCoord,
                });
            }
        },
        onSuccess: async () => {
            const target = pendingProposalValueRef.current;
            posthog.capture('crm_broker_details_proposal_accept_undone', {
                extrato_id: extratoId,
                proposal_uuid: proposalData?.uuid,
                accepted_value: acceptedValueSnapshotRef.current,
                new_value: target,
            });
            pendingProposalValueRef.current = null;
            setUndoAcceptModalOpen(false);

            // Otimista: status volta para "Pendente" já — sem esperar o refetch,
            // `hasAcceptRecorded` cai e o slider/lápis destravam sem re-abrir o modal.
            queryClient.setQueryData(
                [QueryKeys.oficios.item, extratoId],
                (old: DetailedOficioProps | undefined) => {
                    if (!old || !proposalData?.uuid) return old;
                    return {
                        ...old,
                        propostas: old.propostas.map((p) =>
                            p.uuid === proposalData.uuid
                                ? {
                                      ...p,
                                      status: 'Pendente',
                                      ...(target != null
                                          ? { proposta_escolhida: String(target) }
                                          : {}),
                                  }
                                : p,
                        ),
                    };
                },
            );

            sendToastMessage({
                title:
                    target != null
                        ? 'Aceite retirado e proposta atualizada.'
                        : 'Aceite retirado. Agora você pode alterar a proposta.',
                type: 'success',
            });
            if (target != null) {
                // Caminho do slider: aplica o novo valor, sem entrar em edição manual.
                setProposalValue(target);
                setIsEditingProposal(false);
            } else {
                // Caminho do lápis: destrava a edição manual que o broker pediu.
                setInputValue(numberFormat(proposalValue));
                setIsEditingProposal(true);
            }
            await Promise.all([
                queryClient.invalidateQueries({ queryKey: [QueryKeys.oficios.item] }),
                queryClient.invalidateQueries({
                    queryKey: [QueryKeys.propostas.vigente, proposalData?.uuid],
                }),
                queryClient.invalidateQueries({
                    queryKey: [QueryKeys.propostas.checks, proposalData?.uuid],
                }),
                queryClient.invalidateQueries({
                    queryKey: [QueryKeys.broker.dashboardTable],
                    refetchType: 'all',
                }),
            ]);
        },
        onError: (error) => {
            posthog.capture('crm_broker_details_proposal_accept_undo_failed', {
                extrato_id: extratoId,
                proposal_uuid: proposalData?.uuid,
                error: error instanceof Error ? error.message : 'Unknown error',
                ...getBackendErrorAnalyticsProps(error),
            });
            sendToastMessage({
                title: 'Não foi possível retirar o aceite',
                description: getUserFacingApiMessage(
                    error,
                    'Tente novamente ou consulte o coordenador.',
                ),
                type: 'error',
            });
        },
    });

    function openUndoAcceptModal() {
        setUndoAcceptModalOpen((alreadyOpen) => {
            if (alreadyOpen) return alreadyOpen;
            acceptedValueSnapshotRef.current = proposalValue;
            pendingProposalValueRef.current = null;
            posthog.capture('crm_broker_details_proposal_accept_undo_prompted', {
                extrato_id: extratoId,
                proposal_uuid: proposalData?.uuid,
                accepted_value: proposalValue,
            });
            return true;
        });
    }

    function handleKeepAccept() {
        pendingProposalValueRef.current = null;
        setProposalValue(acceptedValueSnapshotRef.current || proposalValue);
        setIsEditingProposal(false);
        setUndoAcceptModalOpen(false);
    }

    function handleEditProposal() {
        if (hasAcceptRecorded) {
            openUndoAcceptModal();
            return;
        }

        if (!inputValue) {
            setInputValue(numberFormat(proposalValue));
        }
        posthog.capture('crm_broker_details_proposal_manual_edit_clicked', {
            extrato_id: extratoId,
            current_value: proposalValue,
        });
        setIsEditingProposal(!isEditingProposal);
    }

    function formatInputValue() {
        setInputValue(formatCurrency(inputValue));
    }

    const handleSliderChange = useCallback(
        (value: string) => {
            const formatedValue = value
                .replace(/R\$\s*/g, '')
                .replace(/\.(?=[^.]*,)/g, '')
                .replace(',', '.');
            const numValue = Number(formatedValue);

            if (hasAcceptRecorded) {
                setUndoAcceptModalOpen((alreadyOpen) => {
                    if (alreadyOpen) return alreadyOpen;
                    acceptedValueSnapshotRef.current = proposalValue;
                    if (!Number.isNaN(numValue)) {
                        pendingProposalValueRef.current = Math.max(
                            minProposal,
                            Math.min(maxProposal, numValue),
                        );
                    }
                    posthog.capture('crm_broker_details_proposal_accept_undo_prompted', {
                        extrato_id: extratoId,
                        proposal_uuid: proposalData?.uuid,
                        accepted_value: proposalValue,
                        new_value: pendingProposalValueRef.current,
                    });
                    return true;
                });
                return;
            }

            if (isNaN(numValue)) return;

            if (numValue < minProposal || numValue > maxProposal) {
                setInputError(true);
                return;
            }

            markMovedRegua();
            setProposalValue(numValue);

            if (inputError) setInputError(false);

            const commission = pricingEngine.calculateCommissionForProposal(numValue);
            const commissionCoord = pricingEngine.calculateCoordinatorCommission(commission);

            captureSliderChangeDebounced(numValue);

            debouncedSave(numValue, commission, commissionCoord);
        },
        [
            hasAcceptRecorded,
            proposalValue,
            extratoId,
            proposalData?.uuid,
            minProposal,
            maxProposal,
            inputError,
            debouncedSave,
            captureSliderChangeDebounced,
            pricingEngine,
        ],
    );

    const wizardProposal = useMemo((): ProposalGeneratorProposal | null => {
        if (!extratoData || !proposalData) return null;
        const uuid = String(proposalData.uuid || extratoId);
        return {
            id: uuid,
            displayId: formatProposalId(uuid),
            creditor: {
                name: extratoData.credor || 'Credor',
                cpf: extratoData.cpf_cnpj || '—',
            },
            asset: {
                debtor: extratoData.ente_devedor || '—',
                nature: extratoData.natureza || '—',
                budgetYear: Number(extratoData.LOA) || new Date().getFullYear(),
                grossValue: Number(extratoData.valor_bruto_atualizado_final) || valorLiquido,
                incomeTax: Number(extratoData.imposto_de_renda) || 0,
                lawyerFees: 0,
                netValue: valorLiquido,
            },
            offer: {
                value: proposalValue,
                min: minProposal,
                max: maxProposal,
                commission: displayedCommission,
            },
            publishedOfferValue: publishedDigitalOffer,
        };
    }, [
        extratoData,
        proposalData,
        extratoId,
        valorLiquido,
        proposalValue,
        minProposal,
        maxProposal,
        displayedCommission,
        publishedDigitalOffer,
    ]);

    const digitalOfferComparison = useMemo(
        () =>
            compareDigitalOfferToCurrent({
                publishedOfferValue: publishedDigitalOffer,
                currentOfferValue: proposalValue,
            }),
        [publishedDigitalOffer, proposalValue],
    );
    const brandKit = useMemo((): BrandKit => {
        const displayName = `${first_name} ${last_name}`.trim() || 'Broker';
        const firmBase = nome_fantasia || razao_social || displayName;
        const location =
            cidade && estado ? ` · ${cidade}/${estado}` : cidade ? ` · ${cidade}` : '';
        const accountAvatar =
            profile_picture &&
            profile_picture.trim() !== '' &&
            profile_picture !== defaultProfilePicture
                ? profile_picture.trim()
                : null;
        return {
            displayName,
            cargo: title || 'Broker credenciado',
            phone: phone ? String(phone) : '',
            email: email || '',
            firm: `${firmBase}${location}`,
            // Logo do escritório só via upload no wizard — foto de perfil não é marca institucional.
            logoUrl: null,
            // Fallback: avatar Celer até haver foto no inventário de marca.
            profilePictureUrl: accountAvatar,
            profilePictures: [],
            defaultProfilePictureId: null,
            accent: '#2563EB',
            defaultTemplateId: null,
            defaultBrandMode: 'co',
        };
    }, [
        first_name,
        last_name,
        title,
        phone,
        email,
        nome_fantasia,
        razao_social,
        cidade,
        estado,
        profile_picture,
    ]);

    function handleOpenWizard() {
        const mode: ProposalWizardMode = hasSentDigital ? 'view' : 'edit';
        setWizardMode(mode);
        setWizardInitialStep(undefined);
        posthog.capture('crm_broker_details_proposal_wizard_opened', {
            extrato_id: extratoId,
            proposal_value: proposalValue,
            wizard_mode: mode,
            has_sent_digital: hasSentDigital,
        });
        setWizardOpen(true);
    }

    /** Done do tour de precificação → abre o wizard e encadeia o tour do dialog. */
    const openWizardFromPricingTour = useCallback(() => {
        setWizardMode('edit');
        setWizardInitialStep(0);
        setWizardTourPending(true);
        posthog.capture('crm_broker_details_proposal_wizard_opened', {
            extrato_id: extratoId,
            proposal_value: proposalValue,
            wizard_mode: 'edit',
            has_sent_digital: hasSentDigital,
            source: 'pricing_tour_done',
        });
        setWizardOpen(true);
    }, [extratoId, proposalValue, hasSentDigital]);

    useEffect(() => {
        registerBrokerPricingTourOnCompleted(openWizardFromPricingTour);
        return () => registerBrokerPricingTourOnCompleted(null);
    }, [openWizardFromPricingTour]);

    const handleWizardOfferChange = useCallback(
        (numValue: number) => {
            handleSliderChange(String(numValue));
        },
        [handleSliderChange],
    );

    // =================
    // # Effects
    // =================
    // Deep links: `regua` → cursor na régua; `brand` → cursor em Gerar proposta → wizard logo.
    useEffect(() => {
        const focus = parsePropostaDigitalQuery(propostaDigitalRaw);
        if (!focus) return;

        let cancelled = false;

        const clearQuery = () => {
            if (cancelled) return;
            void setPropostaDigitalQuery(null);
        };

        if (focus === PROPOSTA_DIGITAL_QUERY.regua) {
            if (isErrorExtratoData || isSemSmartblock) {
                void setPropostaDigitalQuery(null);
                return;
            }
            if (isFetchingExtratoData) return;

            const timer = window.setTimeout(() => {
                if (cancelled) return;
                const started = animateCursorToRegua({ onComplete: clearQuery });
                if (!started) clearQuery();
            }, 420);

            return () => {
                cancelled = true;
                window.clearTimeout(timer);
                killCursorGuide();
            };
        }

        if (!wizardProposal) return;

        const openFromDeepLink = () => {
            if (cancelled) return;
            const openInEdit = focus === PROPOSTA_DIGITAL_QUERY.brand;
            const mode: ProposalWizardMode = openInEdit
                ? 'edit'
                : hasSentDigital
                  ? 'view'
                  : 'edit';
            setWizardMode(mode);
            setWizardInitialStep(openInEdit ? 1 : undefined);
            setWizardOpen(true);
            posthog.capture('crm_broker_details_proposal_wizard_opened', {
                extrato_id: extratoId,
                proposal_value: proposalValue,
                wizard_mode: mode,
                has_sent_digital: hasSentDigital,
                deep_link: focus,
                via_cursor_guide: focus === PROPOSTA_DIGITAL_QUERY.brand,
            });
            clearQuery();
        };

        if (focus === PROPOSTA_DIGITAL_QUERY.open) {
            openFromDeepLink();
            return () => {
                cancelled = true;
            };
        }

        // brand
        const timer = window.setTimeout(() => {
            if (cancelled) return;
            const started = animateCursorToGerarProposta({
                onComplete: openFromDeepLink,
            });
            if (!started) openFromDeepLink();
        }, 420);

        return () => {
            cancelled = true;
            window.clearTimeout(timer);
            killCursorGuide();
        };
        // proposalValue só no analytics; isFetching* evita reinício da régua.
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [
        propostaDigitalRaw,
        wizardProposal?.id,
        hasSentDigital,
        extratoId,
        setPropostaDigitalQuery,
        isFetchingExtratoData,
        isErrorExtratoData,
        isSemSmartblock,
    ]);

    useEffect(() => {
        if (proposalData) {
            // Em repactuação, `propostaEscolhida` é o valor da proposta_nova —
            // não o escolhido congelado da proposta vigente.
            const currentProposal = pricingInput.propostaEscolhida || minProposal;
            setProposalValue(currentProposal);
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [proposalData, pricingInput]);

    // Proposta digital já enviada → botão “Ver proposta” (modo leitura no wizard).
    useEffect(() => {
        const proposalId = proposalData?.uuid ? String(proposalData.uuid) : null;
        if (!proposalId) {
            setHasSentDigital(false);
            setPublishedDigitalOffer(null);
            return;
        }
        let cancelled = false;
        void (async () => {
            const doc = await fetchLatestPropostaDigitalDocumentOrNull(proposalId);
            if (cancelled) return;
            const sentLike = isPropostaDigitalSentLike(doc?.status);
            setHasSentDigital(sentLike);
            setPublishedDigitalOffer(
                sentLike ? parseOfferAmount(doc?.offer_value) : null,
            );
        })();
        return () => {
            cancelled = true;
        };
    }, [proposalData?.uuid, wizardOpen]);

    useEffect(() => {
        if (isEditingProposal && proposalValueInputRef.current) {
            proposalValueInputRef.current.focus();
            proposalValueInputRef.current.select();
        }
    }, [isEditingProposal]);

    useEffect(() => {
        if (!inputValue) return;
        handleSliderChange(inputValue);
    }, [inputValue, handleSliderChange]);

    const pricingTourConfig = useMemo(
        () => ({
            ...createBrokerPricingTourConfig({
                onCompleted: openWizardFromPricingTour,
            }),
            condition: () =>
                !isFetchingExtratoData &&
                !isErrorExtratoData &&
                !isSemSmartblock &&
                Boolean(extratoData) &&
                typeof document !== 'undefined' &&
                Boolean(document.getElementById(BROKER_PRICING_TOUR_IDS.gerarProposta)),
        }),
        [
            openWizardFromPricingTour,
            isFetchingExtratoData,
            isErrorExtratoData,
            isSemSmartblock,
            extratoData,
        ],
    );

    useDriverTour(pricingTourConfig);

    useEffect(() => {
        if (!wizardOpen || !wizardTourPending) return;

        let cancelled = false;
        let attempts = 0;
        let timeoutId = 0;

        const tryLaunch = () => {
            if (cancelled) return;
            const started = launchBrokerProposalWizardTour({
                force: true,
                source: 'from-pricing',
            });
            if (started) {
                setWizardTourPending(false);
                return;
            }
            attempts += 1;
            if (attempts >= 25) {
                setWizardTourPending(false);
                return;
            }
            timeoutId = window.setTimeout(tryLaunch, 120);
        };

        timeoutId = window.setTimeout(tryLaunch, 420);
        return () => {
            cancelled = true;
            window.clearTimeout(timeoutId);
        };
    }, [wizardOpen, wizardTourPending]);

    if (isErrorExtratoData)
        return (
            <ErrorMessageBox
                className="grid grid-cols-2"
                retryFn={refetchExtratoData}
                isRetrying={isFetchingExtratoData}
            />
        );

    if (isFetchingExtratoData) {
        return <ValueCardsAndSliderSkeleton />;
    }

    return (
        <TooltipProvider delayDuration={200}>
        <div className="flex flex-col gap-3 sm:gap-3.5 2xl:gap-4">
            {isSemSmartblock && <SemSmartblockAlert />}

            <div className="relative">
                {isSemSmartblock && <SemSmartblockSliderFrost className="rounded-xl" />}

                <div
                    className={cn(
                        'grid grid-cols-1 gap-2.5 sm:grid-cols-3 sm:gap-3 2xl:gap-4',
                        'sm:items-stretch',
                        isSemSmartblock && 'pointer-events-none select-none',
                    )}
                >
                    <ValueMetricCard tone="brand" icon={Landmark} label="Valor líquido">
                        <div id={BROKER_PRICING_TOUR_IDS.valorLiquido}>
                        <ValueAmount tone="brand">
                            <AnimatedNumber value={Number(valorLiquido)} duration={500} />
                        </ValueAmount>
                        </div>
                    </ValueMetricCard>

                    <ValueMetricCard
                        tone="amber"
                        icon={HandCoins}
                        label="Credor receberá"
                        className={cn(
                            proposalData?.earn_out_ativo && 'overflow-y-auto md:items-start md:justify-start',
                        )}
                    >
                        <div className="relative flex w-full shrink-0 items-center justify-center gap-3">
                            {isEditingProposal ? (
                                <Input
                                    ref={proposalValueInputRef}
                                    type="text"
                                    value={inputValue}
                                    onChange={(e) => setInputValue(e.target.value)}
                                    onBlur={formatInputValue}
                                    className="h-8 min-w-0 max-w-full border-none bg-transparent p-0 text-center font-mono text-base font-bold tabular-nums tracking-tight text-amber-800 outline-none dark:text-amber-200 sm:text-lg xl:text-xl 2xl:h-auto 2xl:text-2xl"
                                />
                            ) : (
                                <ValueAmount tone="amber" className="text-center">
                                    <AnimatedNumber value={Number(proposalValue)} duration={500} />
                                </ValueAmount>
                            )}
                            {!isPricingLocked && (
                                <Button
                                    title={
                                        isEditingProposal
                                            ? 'Cancelar edição'
                                            : 'Editar valor da proposta'
                                    }
                                    variant="ghost"
                                    size="icon"
                                    className="absolute right-0 size-8 shrink-0 rounded-lg text-amber-700 hover:bg-[color-mix(in_srgb,#f59e0b_12%,var(--bento-shell))] dark:text-amber-300"
                                    onClick={handleEditProposal}
                                >
                                    {isEditingProposal ? <X size={14} /> : <Pencil size={14} />}
                                </Button>
                            )}
                            {inputError && (
                                <p className="absolute -bottom-3 left-1/2 w-fit -translate-x-1/2 whitespace-nowrap text-[10px] text-red-600 dark:text-red-400">
                                    Valor deve ser entre {numberFormat(minProposal)} e{' '}
                                    {numberFormat(maxProposal)}
                                </p>
                            )}
                        </div>
                        {proposalData?.earn_out_ativo && (
                            <EarnOutBlock
                                valorLiquido={valorLiquido}
                                proposalValue={proposalValue}
                                proposalMax={maxProposal}
                                metas={[
                                    {
                                        data: proposalData.meta_1_data,
                                        pctMax: proposalData.earn_out_meta_1_percentual
                                            ? parseFloat(proposalData.earn_out_meta_1_percentual)
                                            : 0,
                                    },
                                    {
                                        data: proposalData.meta_2_data,
                                        pctMax: proposalData.earn_out_meta_2_percentual
                                            ? parseFloat(proposalData.earn_out_meta_2_percentual)
                                            : 0,
                                    },
                                    {
                                        data: proposalData.meta_3_data,
                                        pctMax: proposalData.earn_out_meta_3_percentual
                                            ? parseFloat(proposalData.earn_out_meta_3_percentual)
                                            : 0,
                                    },
                                ]}
                                isAcordo={proposalData.earn_out_acordo || false}
                            />
                        )}
                    </ValueMetricCard>

                    <ValueMetricCard tone="success" icon={PiggyBank} label="Sua comissão">
                        <div id={BROKER_PRICING_TOUR_IDS.comissao}>
                        <ValueAmount tone="success">
                            <AnimatedNumber value={Number(displayedCommission)} duration={500} />
                        </ValueAmount>
                        </div>
                    </ValueMetricCard>
                </div>
            </div>

            <section className="relative">
                <div className="absolute right-2 top-2 z-30">
                    {isPricingLocked && !isSemSmartblock && <LockedSectionTooltip />}
                </div>

                <div className="relative">
                    {isSemSmartblock && <SemSmartblockSliderFrost className="rounded-xl" />}

                    <div
                        className={cn(
                            'grid grid-cols-1 items-center gap-3 p-3',
                            'lg:grid-cols-[minmax(10.5rem,1fr)_minmax(0,15rem)_minmax(10.5rem,1fr)] lg:gap-4 lg:p-3.5',
                            '2xl:grid-cols-[minmax(12rem,1fr)_minmax(0,18rem)_minmax(12rem,1fr)] 2xl:gap-6 2xl:p-4',
                            BENTO_SURFACE,
                            hasAcceptRecorded && BROKER_ACCEPT_SURFACE_CLASS,
                            isLocked && !isSemSmartblock ? 'pointer-events-none opacity-50' : '',
                            isSemSmartblock ? 'pointer-events-none select-none' : '',
                        )}
                    >
                        <div
                            className={cn(
                                'hidden space-y-1 p-3 lg:flex lg:self-stretch lg:justify-self-start lg:flex-col lg:items-center lg:justify-center lg:text-center',
                                BENTO_INSET,
                            )}
                        >
                            <span className="block text-xs font-medium text-(--bento-text-muted)">
                                Proposta mínima
                            </span>
                            <div
                                className={cn(
                                    'font-mono text-base font-bold tabular-nums 2xl:text-lg',
                                    pricingAccentMuted,
                                )}
                            >
                                {numberFormat(minProposal)}
                            </div>
                        </div>

                        <div
                            id={BROKER_PRICING_TOUR_IDS.regua}
                            className="mx-auto flex w-full max-w-[15rem] flex-col items-center gap-3 2xl:max-w-[18rem] 2xl:gap-4 lg:justify-self-center"
                        >
                            <div className="flex items-center gap-2 px-1 text-center text-[11px] font-medium leading-snug text-(--bento-text-muted) text-pretty sm:text-xs motion-reduce:**:transition-none">
                                <span className="relative size-4 shrink-0">
                                    <ArrowLeft
                                        className={cn(
                                            'absolute size-4 transition-all duration-200 ease-out motion-reduce:transition-none',
                                            isSaving
                                                ? 'scale-75 opacity-0'
                                                : 'scale-100 opacity-100',
                                        )}
                                    />
                                </span>
                                <span>
                                    {hasAcceptRecorded
                                        ? 'Proposta aceita — mova para desfazer'
                                        : 'Arraste para ajustar a proposta'}
                                </span>
                                <span className="relative size-4 shrink-0">
                                    <ArrowRight
                                        className={cn(
                                            'absolute size-4 transition-all duration-200 ease-out',
                                            isSaving
                                                ? 'scale-75 opacity-0'
                                                : 'scale-100 opacity-100',
                                        )}
                                    />
                                    <Save
                                        className={cn(
                                            'absolute size-4 text-emerald-600 transition-all duration-200 ease-out dark:text-emerald-400',
                                            isSaving
                                                ? 'scale-100 animate-[pulse_2.5s_ease-in-out_infinite] opacity-100'
                                                : 'scale-75 opacity-0',
                                        )}
                                    />
                                </span>
                            </div>

                            <div className="relative w-full px-1">
                                <input
                                    type="range"
                                    min={minProposal}
                                    max={maxProposal}
                                    step={SLIDER_STEP}
                                    value={proposalValue}
                                    onChange={(e) => handleSliderChange(e.target.value)}
                                    style={{
                                        background: `linear-gradient(to right, ${pricingAccent} 0%, ${pricingAccent} ${sliderPercentage}%, color-mix(in srgb, var(--bento-divider) 100%, transparent) ${sliderPercentage}%, color-mix(in srgb, var(--bento-divider) 100%, transparent) 100%)`,
                                    }}
                                    className={cn(
                                        'h-2 w-full cursor-pointer appearance-none rounded-full focus-visible:outline-none focus-visible:ring-2',
                                        '[&::-webkit-slider-thumb]:h-5 [&::-webkit-slider-thumb]:w-5 [&::-webkit-slider-thumb]:appearance-none [&::-webkit-slider-thumb]:rounded-full [&::-webkit-slider-thumb]:border-[3px] [&::-webkit-slider-thumb]:bg-white [&::-webkit-slider-thumb]:shadow-sm',
                                        '[&::-webkit-slider-thumb]:transition-transform motion-reduce:[&::-webkit-slider-thumb]:transition-none [&::-webkit-slider-thumb]:hover:scale-110',
                                        'touch-manipulation',
                                        pricingFocusRing,
                                    )}
                                    aria-label="Ajustar valor da proposta"
                                />

                                {isLocalhost && suggestedProposal > 0 && (
                                    <Tooltip>
                                        <TooltipTrigger asChild>
                                            <button
                                                type="button"
                                                onClick={() => handleSliderChange(suggestedProposal.toString())}
                                                className="absolute top-1/2 h-5 w-[2px] -translate-y-1/2 -translate-x-1/2 rounded-full bg-emerald-500 shadow-xs z-10 cursor-pointer"
                                                style={{ left: getSliderThumbOffsetStyle(suggestedProposalPct) }}
                                                aria-label="Aplicar sugestão de proposta"
                                            />
                                        </TooltipTrigger>
                                        <TooltipContent side="top" sideOffset={6} className="pointer-events-none">
                                            <p className="text-xs font-semibold">Sugerido pelo SmartBlock</p>
                                            <p className="text-xs text-muted-foreground">{numberFormat(suggestedProposal)}</p>
                                        </TooltipContent>
                                    </Tooltip>
                                )}
                            </div>

                            <div className="grid w-full grid-cols-2 gap-2 sm:gap-2.5 lg:hidden">
                                <div className={cn('min-w-0 space-y-1 px-2 py-2 sm:px-2.5 sm:py-2.5', BENTO_INSET)}>
                                    <span className="block text-[11px] font-medium text-(--bento-text-muted) sm:text-xs">
                                        Mínimo
                                    </span>
                                    <div
                                        className={cn(
                                            'whitespace-nowrap font-mono text-[11px] font-bold leading-none tabular-nums tracking-tight sm:text-xs',
                                            pricingAccentMuted,
                                        )}
                                    >
                                        {numberFormat(minProposal)}
                                    </div>
                                </div>
                                <div className={cn('min-w-0 space-y-1 px-2 py-2 sm:px-2.5 sm:py-2.5', BENTO_INSET)}>
                                    <span className="block text-[11px] font-medium text-(--bento-text-muted) sm:text-xs">
                                        Máximo
                                    </span>
                                    <div
                                        className={cn(
                                            'whitespace-nowrap font-mono text-[11px] font-bold leading-none tabular-nums tracking-tight sm:text-xs',
                                            pricingAccentMuted,
                                        )}
                                    >
                                        {numberFormat(maxProposal)}
                                    </div>
                                </div>
                            </div>

                            <div className="w-full space-y-1.5">
                                <GlarePrimaryButton
                                    id={BROKER_PRICING_TOUR_IDS.gerarProposta}
                                    onClick={handleOpenWizard}
                                    disabled={isSemSmartblock}
                                    className={cn(
                                        'min-h-0 h-9 w-full text-[13px] font-semibold disabled:cursor-not-allowed disabled:opacity-50',
                                        hasAcceptRecorded
                                            ? BROKER_ACCEPT_BUTTON_CLASS
                                            : BROKER_BRAND_BUTTON_CLASS,
                                    )}
                                >
                                    <Star className="h-4 w-4" aria-hidden />
                                    {hasSentDigital ? 'Ver proposta' : 'Gerar proposta'}
                                </GlarePrimaryButton>
                                {hasSentDigital && digitalOfferComparison.isMismatch ? (
                                    <p
                                        className="text-[11px] leading-snug text-amber-700"
                                        role="status"
                                    >
                                        Valor do ofício diferente da proposta digital enviada
                                        {digitalOfferComparison.publishedValue != null
                                            ? ` (${numberFormat(digitalOfferComparison.publishedValue)} → ${numberFormat(proposalValue)})`
                                            : ''}
                                        . Abra para regenerar.
                                    </p>
                                ) : null}
                                {hasSentDigital && digitalOfferComparison.isAligned ? (
                                    <p
                                        className="text-center text-[11px] leading-snug text-(--bento-text-muted)"
                                        role="status"
                                    >
                                        Valor alinhado à proposta digital enviada.
                                    </p>
                                ) : null}
                            </div>
                        </div>

                        <div
                            className={cn(
                                'hidden space-y-1 p-3 lg:flex lg:self-stretch lg:justify-self-end lg:flex-col lg:items-center lg:justify-center lg:text-center',
                                BENTO_INSET,
                            )}
                        >
                            <span className="block text-xs font-medium text-(--bento-text-muted)">
                                Proposta máxima
                            </span>
                            <div
                                className={cn(
                                    'font-mono text-base font-bold tabular-nums 2xl:text-lg',
                                    pricingAccentMuted,
                                )}
                            >
                                {numberFormat(maxProposal)}
                            </div>
                        </div>
                    </div>
                </div>
            </section>

            {wizardProposal ? (
                <ProposalWizardDialog
                    open={wizardOpen}
                    onOpenChange={(open) => {
                        setWizardOpen(open);
                        if (!open) {
                            setWizardInitialStep(undefined);
                            setWizardTourPending(false);
                        }
                    }}
                    proposal={wizardProposal}
                    brandKit={brandKit}
                    mode={wizardMode}
                    initialStep={wizardInitialStep}
                    onOfferChange={handleWizardOfferChange}
                    onGenerate={async (payload) => {
                        setHasSentDigital(true);
                        setPublishedDigitalOffer(payload.offerValue);
                        posthog.capture('crm_broker_details_proposal_wizard_generated', {
                            extrato_id: extratoId,
                            template_id: payload.templateId,
                            channels: payload.channels,
                            offer_value: payload.offerValue,
                        });
                    }}
                />
            ) : null}

            <DesfazerAceitePropostaModal
                open={undoAcceptModalOpen}
                acceptedValue={acceptedValueSnapshotRef.current || proposalValue}
                pendingValue={pendingProposalValueRef.current ?? undefined}
                credorName={extratoData?.credor}
                isPending={changeAndRemoveAcceptMutation.isPending}
                onKeepAccept={handleKeepAccept}
                onChangeAndRemove={() => changeAndRemoveAcceptMutation.mutate()}
            />
        </div>
        </TooltipProvider>
    );
}

