import { ValueCardsAndSlider } from '@/app/crm/broker/[id]/_components/ValueCardsAndSlider';
import { formatMessageTime } from '@/functions/chat/formatMessageTime';
import { useIsMobileOrTablet } from '@/hooks/use-mobile-or-tablet';
import { cn } from '@/lib/utils';
import { deleteMessage, editMessage, getAttachmentStreamUrl } from '@/services/chat';
import { Message } from '@/types/message';
import { useMutation } from '@tanstack/react-query';
import { motion } from 'framer-motion';
import { Bot, Check, CheckCheck, ChevronDown, Clock, Download, FileText, FileVideo, Loader, Paperclip, Pencil, Trash2, X } from 'lucide-react';
import { memo, useEffect, useMemo, useRef, useState } from 'react';
import { AudioPlayer } from '../Chat/AudioPlayer';
import ImgDocVisualizer from '../Modals/BrokersDocs/ImgDocVizualizer';
import { PDFViewerModal } from '../Modals/PDFViewerModal';
import { Button } from '../ui/button';
import {
    DropdownMenu,
    DropdownMenuContent,
    DropdownMenuGroup,
    DropdownMenuItem,
    DropdownMenuTrigger,
} from '../ui/dropdown-menu';
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from '../ui/tooltip';

interface MessageCardProps {
    currentUserId: number;
    msg: Message;
    conversationId: string;
    onDeleteClick: (msg: Message) => void;
}

interface AttachmentLike {
    path?: string;
    url?: string;
    file?: string;
    type?: string;
    name?: string;
    filename?: string;
}

/**
 * Componente para exibir uma mensagem individual do chat
 * Memoizado para evitar re-renders desnecessários
 *
 * @param currentUserId - ID do usuário atual para identificar se a mensagem é própria
 * @param msg - Mensagem a ser exibida
 * @param conversationId - ID da conversa
 * @param onDeleteClick - Callback quando o usuário clica para deletar
 */
function MessageCardComponent({ currentUserId, msg, onDeleteClick }: MessageCardProps) {
    const [isEditing, setIsEditing] = useState(false);
    const [editedContent, setEditedContent] = useState(msg.message);
    const [isConfirmingDelete, setIsConfirmingDelete] = useState(false);
    const [isPDFOpen, setIsPDFOpen] = useState(false);
    const [isImgOpen, setIsImgOpen] = useState(false);
    const editableRef = useRef<HTMLDivElement>(null);
    const isMobileOrTablet = useIsMobileOrTablet();

    const isCurrentUser = msg.sender_id === currentUserId;

    /**
     * Formata timestamp da mensagem
     * Memoizado para evitar recálculo a cada render
     */
    const formattedTime = useMemo(() => formatMessageTime(msg.timestamp), [msg.timestamp]);

    useEffect(() => {
        if (isEditing && editableRef.current) {
            // Só define o conteúdo se estiver vazio ou ao iniciar a edição
            if (!editableRef.current.textContent) {
                editableRef.current.textContent = msg.message;
            }

            editableRef.current.focus();
            // Posiciona o cursor no final do texto
            const range = document.createRange();
            const selection = window.getSelection();
            range.selectNodeContents(editableRef.current);
            range.collapse(false);
            selection?.removeAllRanges();
            selection?.addRange(range);
        }
    }, [isEditing, msg.message]);

    const handleEdit = () => {
        setIsEditing(true);
    };

    const editMessageMutation = useMutation({
        mutationFn: async (newMessage: string) => {
            if (newMessage.trim() !== msg.message) {
                await editMessage({
                    message_id: msg._id,
                    new_message: newMessage,
                });
            }
