'use client';

import gsap from 'gsap';
import { useGSAP } from '@gsap/react';
import {
    RotateCcw,
    Fingerprint,
    MousePointerClick,
    ListChecks,
    DollarSign,
    MessageSquare,
    LucideIcon,
} from 'lucide-react';
import { Suspense, lazy, useRef, type ReactNode } from 'react';
import { CommentsSectionSkeleton } from '@/components/Skeletons/Broker/CommentsSectionSkeleton';
import { useBentoCockpitTheme } from '@/app/crm/broker/_hooks/useBentoCockpitTheme';
import { cn } from '@/lib/utils';
import {
    BROKER_COMMENTS_AS_SECTION_MAX_HEIGHT_PX,
} from '@/constants/broker-comments';
import {
    BROKER_DETAILS_BENTO_CARD_IDS,
    BROKER_DETAILS_BENTO_GRID_GAP_PX,
    BrokerDetailsBentoCardId,
} from '../_types/details-bento';
import { useBrokerDetailsBentoLayout } from '../_hooks/useBrokerDetailsBentoLayout';
import { BrokerPricingTourHelpMenu } from '@/app/crm/broker/_components/activation';
import { ExtratoTriggerOverridesPanel } from '@/components/calcform/ExtratoTriggerOverridesPanel';
import { BrokerDetailsBentoCard } from './BrokerDetailsBentoCard';
import { BrokerCallToActionButton } from './BrokerCallToActionButton';
import { OficioDetailsHeader } from './OficioDetailsHeader';
import { RequisitosProgressBadge } from './RequisitosProgressBadge';
import { RequisitosSection } from './RequisitosSection';
import { ValueCardsAndSlider } from './ValueCardsAndSlider';

gsap.registerPlugin(useGSAP);

const BrokerCommentsSectionLazy = lazy(() => import('@/components/CRM/Broker/CommentsSection'));
const OficioCommentsFloatMenuLazy = lazy(
    () => import('@/components/CRM/Broker/OficioCommentsFloatMenu'),
);

interface BrokerDetailsBentoGridProps {
    extratoId: string;
    setActiveTab: (tab: string) => void;
}

const CARD_META: Record<BrokerDetailsBentoCardId, { title: string; icon: LucideIcon }> = {
    identity: { title: 'Identidade do precatório', icon: Fingerprint },
    action: { title: 'Próxima ação', icon: MousePointerClick },
    requirements: { title: 'Requisitos', icon: ListChecks },
    pricing: { title: 'Proposta e comissão', icon: DollarSign },
    comments: { title: 'Comentários', icon: MessageSquare },
};

function getViewportGridTemplateRows(rowCount: number): string {
    return `repeat(${rowCount}, minmax(0, 1fr))`;
}

export function BrokerDetailsBentoGrid({
    extratoId,
    setActiveTab,
}: BrokerDetailsBentoGridProps) {
    const mountRef = useRef<HTMLDivElement>(null);
    const { theme } = useBentoCockpitTheme();
    const {
        gridRef,
        rowCount,
        draggingId,
        dropTargetId,
        getGridStyle,
        resetLayout,
        startDrag,
    } = useBrokerDetailsBentoLayout();

    useGSAP(
        () => {
            gsap.fromTo(
                '[data-bento-card-id]',
                { y: 14, opacity: 0, filter: 'blur(8px)' },
                {
                    y: 0,
                    opacity: 1,
                    filter: 'blur(0px)',
                    stagger: 0.045,
                    duration: 0.42,
                    ease: 'power3.out',
                    clearProps: 'opacity,transform,filter',
                },
            );
        },
        { scope: mountRef },
    );

    function cardProps(id: BrokerDetailsBentoCardId) {
        const style = getGridStyle(id);
        const meta = CARD_META[id];

        return {
            id,
            title: meta.title,
            headerIcon: meta.icon,
            gridColumn: style.gridColumn,
            gridRow: style.gridRow,
            isDragging: draggingId === id,
            isDropTarget: dropTargetId === id,
            onDragStart: startDrag,
        };
    }

    const cards = (
        <>
            <BrokerDetailsBentoCard {...cardProps('identity')} contentClassName="overflow-hidden">
                <div className="flex flex-col gap-3">
                    <OficioDetailsHeader />
                    <ExtratoTriggerOverridesPanel extratoId={extratoId} compact />
                </div>
            </BrokerDetailsBentoCard>

            <BrokerDetailsBentoCard {...cardProps('action')}>
                <BrokerCallToActionButton />
            </BrokerDetailsBentoCard>

            <BrokerDetailsBentoCard
                {...cardProps('requirements')}
                headerEnd={<RequisitosProgressBadge />}
            >
                <RequisitosSection setActiveTab={setActiveTab} />
            </BrokerDetailsBentoCard>

            <BrokerDetailsBentoCard
                {...cardProps('pricing')}
                headerEnd={<BrokerPricingTourHelpMenu />}
            >
                <ValueCardsAndSlider />
            </BrokerDetailsBentoCard>

            <BrokerDetailsBentoCard
                {...cardProps('comments')}
                contentClassName="flex min-h-0 flex-1 flex-col overflow-hidden p-3"
            >
                <Suspense fallback={<CommentsSectionSkeleton className="h-full min-h-0" />}>
                    <BrokerCommentsSectionLazy
                        extratoId={extratoId}
                        hasTitle
                        className="h-full min-h-0"
                    />
                </Suspense>
            </BrokerDetailsBentoCard>
        </>

