'use client';

import { useBentoCockpitTheme } from '@/app/crm/broker/_hooks/useBentoCockpitTheme';
import { CommentsSectionSkeleton } from '@/components/Skeletons/Broker/CommentsSectionSkeleton';
import { cn } from '@/lib/utils';
import {
    DollarSign,
    ListChecks,
    MessageSquare,
    MousePointerClick,
    type LucideIcon,
} from 'lucide-react';
import { Suspense, lazy, type ReactNode } from 'react';
import { BrokerPricingTourHelpMenu } from '@/app/crm/broker/_components/activation';
import { ExtratoTriggerOverridesPanel } from '@/components/calcform/ExtratoTriggerOverridesPanel';
import { BROKER_CRM_COMMENTS_PANEL_HEIGHT_CLASS, BROKER_CRM_COMMENTS_PANEL_STICKY_CLASS } from '@/constants/broker-comments';
import { BrokerCallToActionButton } from './BrokerCallToActionButton';
import {
    cedenteBentoHeaderAccentClass,
    cedenteBentoHeaderIconClass,
    cedenteBentoHeaderLeadClass,
    cedenteBentoHeaderTitleClass,
} from './bentoCedenteClasses';
import { OficioDetailsHeader } from './OficioDetailsHeader';
import { RequisitosProgressBadge } from './RequisitosProgressBadge';
import { RequisitosSection } from './RequisitosSection';
import { ValueCardsAndSlider } from './ValueCardsAndSlider';

const BrokerCommentsSectionLazy = lazy(() => import('@/components/CRM/Broker/CommentsSection'));
const OficioCommentsFloatMenuLazy = lazy(
    () => import('@/components/CRM/Broker/OficioCommentsFloatMenu'),
);

interface OficioDetailsCockpitProps {
    extratoId: string;
    setActiveTab: (tab: string) => void;
}

interface CockpitSectionProps {
    title: string;
    icon: LucideIcon;
    children: ReactNode;
    className?: string;
    contentClassName?: string;
    headerVariant?: 'default' | 'accent';
    headerEnd?: ReactNode;
}

/** Shell da página: mais compacto até notebook; folga atual em 2xl+. */
const COCKPIT_SHELL_CLASS = cn(
    'relative mx-auto flex w-full flex-col gap-3 px-3 py-3',
    'sm:gap-4 sm:px-4 sm:py-4',
    'lg:px-5 lg:py-5',
    'max-w-[min(100%,72rem)]',
    '2xl:max-w-[1600px]',
);

/** Coluna principal + aside: aside mais estreito em xl (notebook). */
const COCKPIT_GRID_CLASS = cn(
    'grid min-h-0 grid-cols-1 gap-3 sm:gap-4',
    'xl:grid-cols-[minmax(0,1fr)_minmax(240px,280px)] xl:items-stretch',
    '2xl:grid-cols-[minmax(0,1fr)_minmax(300px,360px)]',
);

function CockpitSection({
    title,
    icon: Icon,
    children,
    className,
    contentClassName,
    headerVariant = 'default',
    headerEnd,
}: CockpitSectionProps) {
    const { theme } = useBentoCockpitTheme();

    return (
        <section
            className={cn(
                'relative flex min-h-0 flex-col overflow-hidden rounded-2xl border',
                'transition-[box-shadow,border-color] duration-200 motion-reduce:transition-none',
                className,
            )}
            style={{
                background: theme.card,
                borderColor: theme.cardBorder,
                boxShadow: theme.cardShadow,
                color: theme.text,
            }}
        >
            <header
                className={cn(
                    'flex shrink-0 items-center justify-between gap-2',
                    headerVariant === 'default' && 'border-b px-3 py-2',
                    headerVariant === 'accent' && cedenteBentoHeaderAccentClass,
                )}
                style={headerVariant === 'default' ? { borderColor: theme.divider } : undefined}
            >
                {headerVariant === 'accent' ? (
                    <div className={cedenteBentoHeaderLeadClass}>
                        <div className={cedenteBentoHeaderIconClass} aria-hidden>
                            <Icon size={16} strokeWidth={2.25} />
                        </div>
                        <h2 className={cn(cedenteBentoHeaderTitleClass, 'truncate')}>{title}</h2>
                    </div>
                ) : (
                    <div className="flex min-w-0 items-center gap-2">
                        <Icon size={16} className="shrink-0 text-blue-600 dark:text-blue-400" />
                        <h2 className={cn(cedenteBentoHeaderTitleClass, 'truncate')}>{title}</h2>
                    </div>
                )}
                {headerEnd}
            </header>

            <div className={cn('min-h-0 flex-1', contentClassName ?? 'overflow-auto p-3')}>
                {children}
            </div>
        </section>
    );
}

export function OficioDetailsCockpit({
    extratoId,
    setActiveTab,
}: OficioDetailsCockpitProps) {
    return (
        <div className="relative min-h-0 flex-1 font-satoshi">
            <div className={COCKPIT_SHELL_CLASS}>
                <aside className="block xl:hidden" aria-label="Próxima ação">
                    <CockpitSection
                        title="Próxima ação"
                        icon={MousePointerClick}
                        headerVariant="accent"
                        contentClassName="p-2.5 sm:p-3"
                    >
                        <BrokerCallToActionButton />
                    </CockpitSection>
                </aside>

                <div className={COCKPIT_GRID_CLASS}>
                    <div className="flex min-w-0 flex-col gap-3 sm:gap-4">
                        <OficioDetailsHeader />

                        <ExtratoTriggerOverridesPanel extratoId={extratoId} />

                        <CockpitSection
                            title="Proposta e comissão"
                            icon={DollarSign}
                            headerVariant="accent"
                            headerEnd={<BrokerPricingTourHelpMenu />}
                            contentClassName="p-2 sm:p-2.5 2xl:p-3"

