'use client';

import LeadMagnetSlider from '@/components/Sliders/LeadMagnetSlider';
import { Button } from '@/components/ui/button';
import { Dialog } from '@/components/ui/dialog';
import { QueryKeys } from '@/constants/query-keys';
import { useOficiosTableContext } from '@/context/OficiosTableContext';
import {
    ProductDialogContent,
    ProductDialogDescription,
    ProductDialogFooter,
    ProductDialogHeader,
    ProductDialogTitle,
    productDialogBodyClass,
    productDialogOutlineButtonClass,
    productDialogPrimaryButtonClass,
} from '@/design-system';
import { generateProposalFromExtrato } from '@/services/oficios';
import { OficioProposta } from '@/types/oficio';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { AnimatePresence, motion } from 'framer-motion';
import { Loader2 } from 'lucide-react';
import { useState } from 'react';

import errorAnimation from '@/animations/icons/error.json';
import checkAnimation from '@/animations/icons/success.json';
import { LottieAnimation } from '@/components/Lottie/LottieAnimation';
import { AxiosError } from 'axios';

const variants = {
    initial: { opacity: 0, x: 20 },
    enter: { opacity: 1, x: 0 },
    exit: { opacity: 0, x: -20 },
};

export const CreateProposalFromExtratoModal = () => {
    const { isNewProposalModalOpen, setIsNewProposalModalOpen, extratoInfo, setExtratoInfo } =
        useOficiosTableContext();
    const [backendResponse, setBackendResponse] = useState<OficioProposta | null>(null);
    const [errorMessage, setErrorMessage] = useState('');
    const [step, setStep] = useState(1);
    const queryClient = useQueryClient();

    const { mutate, isPending, isSuccess, isError, reset } = useMutation({
        mutationFn: (id: string) => generateProposalFromExtrato(id),
        onSuccess: (data) => {
            setBackendResponse(data);
            queryClient.invalidateQueries({ queryKey: [QueryKeys.oficios.list] });
            queryClient.invalidateQueries({
                queryKey: [QueryKeys.broker.dashboardTable],
                type: 'all',
            });
            queryClient.invalidateQueries({
                queryKey: [QueryKeys.oficios.item, extratoInfo?.id],
                type: 'all',
            });

            setTimeout(() => setStep(3), 1500);
        },
        onError: (error) => {
            if (error instanceof AxiosError) {
                setErrorMessage(error.response?.data?.detail || 'Ocorreu um erro inesperado.');
            }
        },
    });

    const handleClose = () => {
        setIsNewProposalModalOpen(false);
        setExtratoInfo(null);
        setStep(1);
        reset();
    };

    const handleOpenChange = (open: boolean) => {
        if (!open) {
            handleClose();
        }
    };

    const handleConfirm = () => {
        if (extratoInfo?.id) {
            setStep(2);
            mutate(extratoInfo.id);
        }
    };

    return (
        <Dialog open={isNewProposalModalOpen} onOpenChange={handleOpenChange}>
            <ProductDialogContent size={step === 3 ? 'lg' : 'md'}>
                <AnimatePresence mode="wait">
                    {step === 1 ? (
                        <motion.div
                            key="step1"
                            variants={variants}
                            initial="initial"
                            animate="enter"
                            exit="exit"
                        >
                            <ProductDialogHeader>
                                <ProductDialogTitle>Criar proposta</ProductDialogTitle>

