const getRandomSuggestions = (count: number = 5): string[] => {
    const shuffled = [...allSuggestions].sort(() => Math.random() - 0.5);
    return shuffled.slice(0, count);
};

interface PendingChatAttachment extends AttachmentPreviewItem {
    file: File;
    uploadedAttachment?: AiAttachment;
}

function createPendingAttachment(file: File): PendingChatAttachment {
    return {
        id: `${file.name}-${file.size}-${file.lastModified}-${crypto.randomUUID()}`,
        name: file.name,
        file,
        contentType: file.type,
        size: file.size,
        status: 'selected',
        previewUrl: file.type.startsWith('image/') ? URL.createObjectURL(file) : undefined,
    };
}

function getAttachmentUserText(input: string, attachments: PendingChatAttachment[]): string {
    return input.trim() || attachments.map(({ name }) => `[ARQUIVO: ${name}]`).join('\n');
}

function AtivosIntelligencePageContent() {
    const pathname = usePathname();
    const searchParams = useSearchParams();
    const router = useRouter();
    const { data: user } = useUserInfoStore();
    const permissions = useUserInfoStore((state) => state.permissions);
    const canViewDailyBriefing =
        permissions === null || permissions.includes(Permissions.VIEW_DAILY_BRIEFING);
    // R7-13: explicit RBAC check — without this, users without
    // VIEW_ATIVOS_INTELLIGENCE_CHAT who navigate directly via URL throw
    // inside downstream hooks and hit the generic error boundary ("OOOPS")
    // instead of seeing a clear "access denied" message.
    const [input, setInput] = useState('');
    const [pendingAttachments, setPendingAttachments] = useState<PendingChatAttachment[]>([]);
    const [multimodalLoadingCopy, setMultimodalLoadingCopy] = useState<{
        title: string;
        description: string;
    } | null>(null);
    const [showHistory, setShowHistory] = useState(true);
    const [mobileSidebarOpen, setMobileSidebarOpen] = useState(false);
    const [refiningMessageId, setRefiningMessageId] = useState<string | null>(null);
    const scrollContainerRef = useRef<HTMLDivElement>(null);
    const composerRef = useRef<HTMLDivElement>(null);
    const inputRef = useRef<HTMLTextAreaElement>(null);
    const pendingAttachmentsRef = useRef<PendingChatAttachment[]>([]);
    const lastLoggedChatError = useRef<string | null>(null);
    const pageViewLogged = useRef(false);
    const [editingTitleId, setEditingTitleId] = useState<string | null>(null);
    const [markdownCopied, setMarkdownCopied] = useState(false);
    const [isSettingsOpen, setIsSettingsOpen] = useState(false);
    const [isMemoryConsentPromptOpen, setIsMemoryConsentPromptOpen] = useState(false);
    const [composerInset, setComposerInset] = useState(120);
    const [logoError, setLogoError] = useState(false);
    // Persist PDF context for subsequent messages (e.g., "Cadastrar")
    const [pdfContext, setPdfContext] = useState<Record<string, unknown> | null>(null);
    const [suggestions] = useState<string[]>(() => getRandomSuggestions(5));

    const {
        sendMessage,
        createNewConversation,
        conversations,
        fetchConversations,
        switchConversation,
        isLoadingConversations,
        archiveConversation,
        deleteConversation,
        updateConversationTitle,
        cancelTurn,
        isConnected
    } = useAiChat();

