import '@/app/crm/broker-dashboard/broker-bento-theme.css';
import { Metadata } from 'next';
import { redirect } from 'next/navigation';
import { Suspense } from 'react';

import { APP_ROUTES } from '@/constants/app-routes';

import { isBrokerRole } from '../_helpers/is-broker-v4-enabled';
import { resolveBrokerV4Context } from '../_helpers/resolve-broker-v4-enabled';
import { BrokerOficioDetailsRouteSkeleton } from './_components/BrokerOficioDetailsRouteSkeleton';
import { OficioDetailsTabs } from './_components/OficioDetailsTabs';

export const metadata: Metadata = {
    title: 'CelerApp | Detalhes do Oficio',
    description: 'Página de detalhes do oficio selecionado.',
    category: 'Detalhes do Oficio',
    openGraph: {
        title: 'CelerApp | Detalhes do Oficio',
        description: 'Página de detalhes do oficio selecionado.',
    },
    applicationName: 'CelerApp',
};

export default async function DetalhesDoOficioPage({
    params,
}: {
    params: Promise<{ id: string }>;
}) {
    const { id } = await params;

    // /crm/broker/[id] é o detalhe do broker — com ou sem o cutover V4 (a tabela
    // Precatórios Cadastrados linka pra cá desde antes do 4.0). Quem não é role de
    // broker (staff/Due/jurídico) vai para o detalhe clássico, espelhando o
    // redirect inverso de /crm/oficios/[id]. Só redireciona com role resolvida:
    // falha transitória na validação não pode derrubar o broker pra tela de staff.
    // Fica na page (não no layout) pra não derrubar /memoria, que staff acessa por
    // links gerados em telas da Due/jurídico/financeiro.
    const { role } = await resolveBrokerV4Context();
    if (role && !isBrokerRole(role)) {
        redirect(APP_ROUTES.private.oficiosDetails.name(id));
    }

    return (
        <div className="broker-bento-cockpit h-full min-h-0 overflow-y-auto">
            <Suspense fallback={<BrokerOficioDetailsRouteSkeleton />}>
                <OficioDetailsTabs id={id} />
            </Suspense>
        </div>
    );
}

