'use client';

import { OficiosCockpitStrip } from '@/app/crm/oficios/components/OficiosCockpitStrip';
import { OficiosDataTable } from '@/app/crm/oficios/table/oficios-data-table';
import {
    OficiosFiltersProvider,
    useOficiosTableFilters,
} from '@/app/crm/oficios/use-oficios-table-filters';
import { OficiosTableProvider } from '@/context/OficiosTableContext';
import { OperationalPageHeader } from '@/design-system';
import { FileText } from 'lucide-react';

function BrokerOficiosContent() {
    const { filters } = useOficiosTableFilters();

    return (
        <div className="flex flex-col gap-6">
            <OperationalPageHeader
                aria-label="Cabeçalho da distribuição de ofícios"
                title="Distribuição de Ofícios"
                subtitle="Triagem, acompanhamento de pipeline e criação de propostas a partir dos extratos."
                icon={FileText}
            />

            <OficiosCockpitStrip filters={filters} />

            <OficiosDataTable />
        </div>
    );
}

export function BrokerOficios() {
    return (
        <OficiosTableProvider>
            <OficiosFiltersProvider>
                <BrokerOficiosContent />
            </OficiosFiltersProvider>
        </OficiosTableProvider>
    );
}

